"use client";

import { useMemo, useState } from "react";
import {
  useReactTable,
  getCoreRowModel,
  getSortedRowModel,
  flexRender,
  type SortingState,
} from "@tanstack/react-table";
import { motion } from "framer-motion";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Card } from "@/components/ui/card";
import { ScrollArea } from "@/components/ui/scroll-area";
import { FileInfo } from "@/components/upload/file-info";
import { Icon } from "@/components/shared/icon";
import type { ParsedCSV } from "@/types";

interface CsvPreviewProps {
  csv: ParsedCSV;
  onConfirm: () => void;
  onBack: () => void;
  isUploading: boolean;
}

export function CsvPreview({ csv, onConfirm, onBack, isUploading }: CsvPreviewProps) {
  const [sorting, setSorting] = useState<SortingState>([]);

  const columns = useMemo(
    () =>
      csv.headers.map((header) => ({
        id: header,
        accessorFn: (row: Record<string, string>) => row[header] || "",
        header: () => (
          <span className="font-medium">{header}</span>
        ),
        cell: (info: any) => (
          <span className="max-w-[200px] truncate block" title={String(info.getValue())}>
            {String(info.getValue()) || <span className="text-stone italic">empty</span>}
          </span>
        ),
      })),
    [csv.headers]
  );

  const previewRows = useMemo(() => csv.rows.slice(0, 100), [csv.rows]);

  const table = useReactTable({
    data: previewRows,
    columns,
    state: { sorting },
    onSortingChange: setSorting,
    getCoreRowModel: getCoreRowModel(),
    getSortedRowModel: getSortedRowModel(),
  });

  return (
    <motion.div
      initial={{ opacity: 0, y: 20 }}
      animate={{ opacity: 1, y: 0 }}
      className="max-w-6xl mx-auto"
    >
      <div className="flex items-center justify-between mb-6">
        <div>
          <h2 className="text-2xl font-medium text-ink-black tracking-tight">
            Preview your data
          </h2>
          <p className="text-stone text-sm mt-1">
            Showing first {previewRows.length} of {csv.totalRows.toLocaleString()} rows
          </p>
        </div>
        <div className="flex items-center gap-3">
          <Button variant="ghost" onClick={onBack} disabled={isUploading}>
            <Icon name="arrowLeft" size={16} className="mr-2" />
            Back
          </Button>
          <Button onClick={onConfirm} disabled={isUploading} size="lg">
            {isUploading ? (
              <>
                <Icon name="spinner" size={16} className="mr-2" />
                Uploading...
              </>
            ) : (
              <>
                Confirm Import
                <Icon name="arrowRight" size={16} className="ml-2" />
              </>
            )}
          </Button>
        </div>
      </div>

      <FileInfo
        fileName={csv.fileName}
        fileSize={csv.fileSize}
        totalRows={csv.totalRows}
        headers={csv.headers}
        className="mb-6"
      />

      <Card className="p-0 overflow-hidden">
        <ScrollArea className="h-[500px]">
          <table className="w-full text-sm">
            <thead className="sticky top-0 z-10 bg-paper-warmth border-b border-black/8">
              {table.getHeaderGroups().map((headerGroup) => (
                <tr key={headerGroup.id}>
                  {headerGroup.headers.map((header) => {
                    const isSorted = sorting.some((s) => s.id === header.id);
                    return (
                      <th
                        key={header.id}
                        className="px-4 py-3 text-left font-medium text-stone text-xs cursor-pointer hover:bg-black/5 transition-colors"
                        onClick={header.column.getToggleSortingHandler()}
                      >
                        <div className="flex items-center gap-1">
                          {flexRender(header.column.columnDef.header, header.getContext())}
                          {isSorted && (
                            <span className="text-notion-blue">
                              {header.column.getIsSorted() === "asc" ? "↑" : "↓"}
                            </span>
                          )}
                        </div>
                      </th>
                    );
                  })}
                </tr>
              ))}
            </thead>
            <tbody>
              {table.getRowModel().rows.map((row) => (
                <tr key={row.id} className="border-b border-black/5 hover:bg-paper-warmth/50 transition-colors">
                  {row.getVisibleCells().map((cell) => (
                    <td key={cell.id} className="px-4 py-2.5 text-graphite">
                      {flexRender(cell.column.columnDef.cell, cell.getContext())}
                    </td>
                  ))}
                </tr>
              ))}
            </tbody>
          </table>
        </ScrollArea>
      </Card>

      <div className="mt-4 flex items-center justify-between text-xs text-stone">
        <span>
          {csv.totalRows.toLocaleString()} total rows · {csv.headers.length} columns
        </span>
        <span>
          Scroll to see more data
        </span>
      </div>
    </motion.div>
  );
}
