"use client";

import { useCallback, useState } from "react";
import { useDropzone } from "react-dropzone";
import { motion, AnimatePresence } from "framer-motion";
import { cn } from "@/lib/utils";
import { Icon } from "@/components/shared/icon";

interface DropzoneProps {
  onFileSelect: (file: File) => void;
  isProcessing: boolean;
}

export function Dropzone({ onFileSelect, isProcessing }: DropzoneProps) {
  const [error, setError] = useState<string | null>(null);

  const onDrop = useCallback(
    (acceptedFiles: File[]) => {
      setError(null);
      const file = acceptedFiles[0];
      if (file) {
        if (file.size > 50 * 1024 * 1024) {
          setError("File size exceeds 50MB limit");
          return;
        }
        if (!file.name.endsWith(".csv") && !file.name.endsWith(".tsv")) {
          setError("Please upload a CSV file");
          return;
        }
        onFileSelect(file);
      }
    },
    [onFileSelect]
  );

  const { getRootProps, getInputProps, isDragActive } = useDropzone({
    onDrop,
    accept: { "text/csv": [".csv"], "text/tab-separated-values": [".tsv"] },
    maxFiles: 1,
    disabled: isProcessing,
  });

  return (
    <motion.div
      initial={{ opacity: 0, y: 20 }}
      animate={{ opacity: 1, y: 0 }}
      transition={{ delay: 0.1 }}
      className="max-w-2xl mx-auto"
    >
      <div className="text-center mb-8">
        <h1 className="text-4xl sm:text-5xl font-medium text-ink-black tracking-tight" style={{ letterSpacing: "-0.02em" }}>
          Import your
          <span className="relative inline-block mx-3">
            <span className="relative z-10">CSV</span>
            <motion.span
              initial={{ scaleX: 0 }}
              animate={{ scaleX: 1 }}
              transition={{ delay: 0.5, duration: 0.4 }}
              className="absolute bottom-1 left-0 right-0 h-3 bg-marigold/40 -z-0 origin-left"
            />
          </span>
          data
        </h1>
        <p className="mt-4 text-graphite text-lg">
          Drop any CSV file. Our AI will map columns intelligently.
        </p>
      </div>

      <div
        {...getRootProps()}
        className={cn(
          "relative border-2 border-dashed rounded-cards p-12 text-center cursor-pointer transition-all duration-200",
          isDragActive
            ? "border-notion-blue bg-sky-tint/50"
            : "border-black/15 hover:border-notion-blue/50 hover:bg-white",
          isProcessing && "opacity-50 cursor-not-allowed"
        )}
        style={{ backgroundColor: isDragActive ? undefined : "#ffffff" }}
      >
        <input {...getInputProps()} />
        
        <motion.div
          animate={isDragActive ? { scale: 1.05, y: -5 } : { scale: 1, y: 0 }}
          className="flex flex-col items-center gap-4"
        >
          <div className={cn(
            "w-16 h-16 rounded-full flex items-center justify-center transition-colors",
            isDragActive ? "bg-notion-blue/10" : "bg-paper-warmth"
          )}>
            <Icon name="upload" size={28} className={isDragActive ? "text-notion-blue" : "text-graphite"} />
          </div>
          <div>
            <p className="text-graphite font-medium">
              {isDragActive ? "Drop your CSV here" : "Drag & drop your CSV file"}
            </p>
            <p className="text-stone text-sm mt-1">
              or click to browse. Max 50MB.
            </p>
          </div>
          <div className="flex items-center gap-4 mt-2">
            {[".csv", ".tsv", "Excel export", "Any format"].map((type) => (
              <span key={type} className="text-xs text-stone bg-paper-warmth px-3 py-1 rounded-pills">
                {type}
              </span>
            ))}
          </div>
        </motion.div>
      </div>

      <AnimatePresence>
        {error && (
          <motion.div
            initial={{ opacity: 0, y: -10 }}
            animate={{ opacity: 1, y: 0 }}
            exit={{ opacity: 0 }}
            className="mt-4 p-4 bg-red-50 border border-coral/20 rounded-cards text-coral text-sm"
          >
            {error}
          </motion.div>
        )}
      </AnimatePresence>

      <div className="mt-8 grid grid-cols-3 gap-4">
        {[
          { icon: "🤖", title: "AI-Powered", desc: "Smart column mapping" },
          { icon: "🔒", title: "Secure", desc: "Your data stays private" },
          { icon: "⚡", title: "Fast", desc: "Process 50k+ rows" },
        ].map((feature) => (
          <motion.div
            key={feature.title}
            whileHover={{ y: -2 }}
            className="bg-white border border-black/8 rounded-cards p-4 text-center"
          >
            <div className="text-2xl mb-2">{feature.icon}</div>
            <h3 className="text-sm font-medium text-graphite">{feature.title}</h3>
            <p className="text-xs text-stone mt-1">{feature.desc}</p>
          </motion.div>
        ))}
      </div>
    </motion.div>
  );
}
