import * as React from "react";
import { cn } from "@/lib/utils";

interface ButtonProps extends React.ButtonHTMLAttributes<HTMLButtonElement> {
  variant?: "primary" | "ghost" | "outline" | "secondary";
  size?: "sm" | "md" | "lg";
}

const Button = React.forwardRef<HTMLButtonElement, ButtonProps>(
  ({ className, variant = "primary", size = "md", ...props }, ref) => {
    return (
      <button
        className={cn(
          "inline-flex items-center justify-center font-medium transition-all duration-200 rounded-buttons disabled:opacity-50 disabled:cursor-not-allowed",
          variant === "primary" && "bg-notion-blue text-white hover:bg-notion-blue/90",
          variant === "ghost" && "bg-transparent text-graphite hover:bg-black/5",
          variant === "outline" && "bg-transparent text-graphite border border-black/15 hover:bg-black/5",
          variant === "secondary" && "bg-sky-tint text-notion-blue hover:bg-sky-tint/80",
          size === "sm" && "px-3 py-1.5 text-xs",
          size === "md" && "px-4 py-2 text-sm",
          size === "lg" && "px-6 py-3 text-base",
          className
        )}
        ref={ref}
        {...props}
      />
    );
  }
);
Button.displayName = "Button";
export { Button };
