"use client";

import { motion } from "framer-motion";
import { STAGES } from "@/lib/constants";
import type { AppStep } from "@/types";

const stepIndex: Record<AppStep, number> = {
  upload: 0,
  preview: 1,
  processing: 2,
  results: 3,
};

export function StepIndicator({ currentStep }: { currentStep: AppStep }) {
  const current = stepIndex[currentStep];

  return (
    <div className="mb-12">
      <div className="flex items-center justify-center gap-2">
        {STAGES.map((stage, i) => {
          const isActive = i === current;
          const isCompleted = i < current;

          return (
            <div key={stage.id} className="flex items-center">
              <div className="flex items-center gap-2">
                <motion.div
                  animate={{
                    backgroundColor: isCompleted ? "#0075de" : isActive ? "#000000" : "transparent",
                    scale: isActive ? 1.1 : 1,
                  }}
                  className="w-7 h-7 rounded-full flex items-center justify-center border-2 transition-colors"
                  style={{
                    borderColor: isCompleted ? "#0075de" : isActive ? "#000000" : "rgba(0,0,0,0.15)",
                  }}
                >
                  {isCompleted ? (
                    <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="white" strokeWidth="3" strokeLinecap="round" strokeLinejoin="round">
                      <polyline points="20 6 9 17 4 12" />
                    </svg>
                  ) : (
                    <span className={`text-xs font-medium ${isActive ? "text-white" : "text-stone"}`}>
                      {i + 1}
                    </span>
                  )}
                </motion.div>
                <span className={`text-xs font-medium hidden sm:block ${isActive ? "text-ink-black" : isCompleted ? "text-notion-blue" : "text-stone"}`}>
                  {stage.label}
                </span>
              </div>
              {i < STAGES.length - 1 && (
                <div className="w-8 sm:w-12 h-px mx-2" style={{ backgroundColor: isCompleted ? "#0075de" : "rgba(0,0,0,0.1)" }} />
              )}
            </div>
          );
        })}
      </div>
    </div>
  );
}
